import ifcopenshell
import ifcopenshell.util.element

path_ifc_model = '/home/sffc348/Repos/cobbie/acc/bim_models/dental_clinic/arc.ifc'
model = ifcopenshell.open(path_ifc_model)

stairs = model.by_type('IfcStair')
slabs = model.by_type('IfcSlab')

print("=== Analyzing Stair-Slab Relationships ===\n")

for stair in stairs:
    print(f"Stair: {stair.Name} (GUID: {stair.GlobalId})")

    # Check IfcRelAggregates (decomposition)
    rels = stair.IsDecomposedBy
    if rels:
        print(f"  DecomposedBy ({len(rels)}):")
        for rel in rels:
            if rel.RelatedObjects:
                for obj in rel.RelatedObjects:
                    print(f"    - {obj.is_a()}: {obj.Name or 'No name'} (GUID: {obj.GlobalId})")
    else:
        print(f"  No IsDecomposedBy relationships")

    # Check IfcRelConnectsPathElements or similar connection relationships
    all_inverses = model.get_inverse(stair)
    connect_rels = [r for r in all_inverses if 'Connect' in r.is_a()]
    if connect_rels:
        print(f"  Connection relationships ({len(connect_rels)}):")
        for rel in connect_rels:
            print(f"    - {rel.is_a()}")
    else:
        print(f"  No connection relationships")

    print()

print("\n=== All Slabs in Model ===")
for slab in slabs:
    print(f"Slab: {slab.Name} (GUID: {slab.GlobalId})")
    # Check what the slab is contained in (spatial structure)
    contained = slab.ContainedInStructure
    if contained:
        for rel in contained:
            if rel.RelatingStructure:
                print(f"  Contained in: {rel.RelatingStructure.is_a()} - {rel.RelatingStructure.Name or 'No name'}")
